:"NEED_SENSITIVE","ownershipFilter":"t.actor_account_id=REQUEST_ACCOUNT and a.worker_account_id=REQUEST_ACCOUNT"},{"key":"ownLocationCommands","fields":["agreementId","agreementVersion","kind","state","createdAt"],"dataClass":"COMMAND_LEDGERS","ownershipFilter":"t.actor_account_id=REQUEST_ACCOUNT and REQUEST_ACCOUNT in(a.requester_account_id,a.worker_account_id)"},{"key":"ownAcceptedTaskMedia","fields":["agreementId","agreementVersion","needId","needRevision","state","assets","capturedAt","bytesIncluded"],"dataClass":"MEDIA_OBJECTS","ownershipFilter":"t.account_id=REQUEST_ACCOUNT and a.requester_account_id=REQUEST_ACCOUNT"},{"key":"ownSupportCases","fields":["id","caseNumber","channel","topic","title","desiredOutcome","context","status","revision","createdAt","updatedAt"],"dataClass":"AUDIT_SECURITY_LOGS","ownershipFilter":"t.account_id=REQUEST_ACCOUNT"},{"key":"ownSupportEvents","fields":["id","caseId","sequence","kind","authorRole","body","decisionId","appealId","createdAt"],"dataClass":"AUDIT_SECURITY_LOGS","ownershipFilter":"c.account_id=REQUEST_ACCOUNT"},{"key":"ownSupportDecisions","fields":["id","caseId","caseRevision","outcome","reasonCode","explanation","effect","evidenceIds","priorDecisionId","createdAt"],"dataClass":"AUDIT_SECURITY_LOGS","ownershipFilter":"c.account_id=REQUEST_ACCOUNT"},{"key":"ownSupportAppeals","fields":["id","caseId","decisionId","status","decisionResultId","createdAt"],"dataClass":"AUDIT_SECURITY_LOGS","ownershipFilter":"t.account_id=REQUEST_ACCOUNT and c.account_id=REQUEST_ACCOUNT"},{"key":"ownSupportEvidence","fields":["id","caseId","eventId","reference","createdAt","bytesIncluded"],"dataClass":"AUDIT_SECURITY_LOGS","ownershipFilter":"t.submitted_by_account_id=REQUEST_ACCOUNT and c.account_id=REQUEST_ACCOUNT"},{"key":"ownSupportCommands","fields":["kind","state","caseId","createdAt"],"dataClass":"COMMAND_LEDGERS","ownershipFilter":"t.account_id=REQUEST_ACCOUNT"},{"key":"ownSupportReadMarkers","fields":["caseId","sequence","updatedAt