'policies',(select jsonb_agg(to_jsonb(p)-'oid'-'polrelid' order by polname) from pg_policy p where polrelid=c.oid)) order by n.nspname,c.relname) surface from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.oid in('public.notification_push_attempts'::regclass,'public.notification_deliveries'::regclass,'public.notification_push_devices'::regclass)) surface_check) is distinct from 'a71670bea0420c1223f3d094fe56e089'
