 for r in select * from (values ('public.rpc_claim_push_transport(text)','f70229927ca68419e5ca735a5b64b2e9'),('public.rpc_begin_push_send(uuid,uuid)','0de54bdd7ddcea92dfa697ade808155f'),('public.rpc_complete_push_transport(uuid,uuid,text,text)','d87908db1908b8c88fe66228c5b07f9f'),('private.admit_push_single_target_v1(uuid,uuid,uuid,text,uuid,uuid,uuid,bigint,uuid,timestamptz,timestamptz)','5c3ff77eae79eeaf043298fb91490577'),('public.rpc_claim_push_single_target(uuid)','922d9c6f68bac7cf615e574ca512c70c'),('public.rpc_claim_push_single_target_receipt(uuid)','b8c30ebf3ced3a073189f0c0865217dd'),('private.revoke_push_single_target_v1(uuid)','97c59ee2c8b31173b7862c1620b4e523')) x(signature,expected) loop
