'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped and not (c.oid='public.notification_push_attempts'::regclass and a.attname=any(array['single_target_admission','single_target_claimed_at','single_target_authorization_id']))),
'constraints',(select jsonb_agg(jsonb_build_object('name',conname,'definition',pg_get_constraintdef(oid),'validated',convalidated) order by conname) from pg_constraint where conrelid=c.oid and not (c.oid='public.notification_push_attempts'::regclass and conname=any(array['push_single_target_shape_v1','push_single_target_claim_shape_v1','push_single_target_authorization_v1','push_single_target_authorization_shape_v1']))),
'indexes',(select jsonb_agg(pg_get_indexdef(indexrelid) order by indexrelid::regclass::text) from pg_index where indrelid=c.oid and indexrelid is distinct from to_regclass('public.push_single_target_authorization_v1')),
'triggers',(select jsonb_agg(jsonb_build_object('name',tgname,'definition',pg_get_triggerdef(t.oid),'enabled',tgenabled) order by tgname) from pg_trigger t where tgrelid=c.oid and not tgisinternal),
'policies',(select jsonb_agg(to_jsonb(p)-'oid'-'polrelid' order by polname) from pg_policy p where polrelid=c.oid)) order by n.nspname,c.relname) surface from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.oid in('public.notification_push_attempts'::regclass,'public.notification_deliveries'::regclass,'public.notification_push_devices'::regclass))s) is distinct from 'a71670bea0420c1223f3d094fe56e089'
union all
select 'NEW_COLUMNS_DRIFT' where (select count(*) from pg_attribute where attrelid='public.notification_push_attempts'::regclass and not attisdropped and attname=any(array['single_target_admission','single_target_claimed_at','single_target_authorization_id']) and not attnotnull and ((attname='single_target_admission' and atttypid='jsonb'::regtype) or (attname='single_target_claimed_at' and atttypid='timestamptz'::regtype) or (attname='single_target_authorization_id' and atttypid='uuid'::regtype)))<>3
union all
select 'NEW_CONSTRAINTS_DRIFT' where (select count(*) from pg_constraint where conrelid='public.notification_push_attempts'::regclass and conname=any(array['push_single_target_shape_v1','push_single_target_claim_shape_v1','push_single_target_authorization_v1','push_single_target_authorization_shape_v1']) and convalidated)<>4
union all
select 'NEW_FUNCTION_AUTHORITY_DRIFT:'||s from unnest(array['private.admit_push_single_target_v1(uuid,uuid,uuid,text,uuid,uuid,uuid,bigint,uuid,timestamptz,timestamptz)','public.rpc_claim_push_single_target(uuid)','public.rpc_claim_push_single_target_receipt(uuid)','private.revoke_push_single_target_v1(uuid)'])s left join pg_proc p on p.oid=to_regprocedure(s) where pg_get_userbyid(p.proowner) is distinct from 'postgres' or p.proconfig is distinct from array['search_path=pg_catalog']::text[] or p.prosecdef is distinct from (s like 'public.%') or has_function_privilege('anon',s,'EXECUTE') or has_function_privilege('authenticated',s,'EXECUTE') or has_function_privilege('service_role',s,'EXECUTE') is distinct from (s like 'public.%')
union all
select 'POST_CERTIFICATE_INCONSISTENT' where private.retention_ai_source_ready() is distinct from true or private.closure_source_digest_v5() is distinct from (select sha256 from private.closure_source_v5 where singleton) or private.closure_source_digest_v5() is distinct from (select sha256 from private.closure_erasure_source_v5 where singleton) or private.closure_source_digest_v5() is distinct from private.closure_erasure_binding_v5()->>'sourceSha256' or private.closure_source_digest_v5()='3a785d423a564a5b39f55f916c536753ac73c4a76664ce0a09394ee68909cd23'
union all
select 'READINESS_BODY_DRIFT' where (select md5(replace(replace(prosrc,chr(13),''),(select sha256 from private.closure_source_v5 where singleton),'3a785d423a564a5b39f55f916c536753ac73c4a76664ce0a09394ee68909cd23')) from pg_proc where oid='private.retention_ai_source_ready()'::regprocedure) is distinct from 'cd4bd5ecf09fefac1b9d7cdea8089630') select jsonb_build_object('package','PUSH_SINGLE_TARGET_V1','sourceSha','74cdca32bc48b9dfb95622bdd26920878797b805','checkedAt',clock_timestamp(),'problems',coalesce((select jsonb_agg(problem order by problem) from problems),'[]'::jsonb),'sourceRoster',108,'computedDigest',private.closure_source_digest_v5(),'sourceRow',(select to_jsonb(c) from private.closure_source_v5 c where singleton),'erasureRow',(select to_jsonb(c) from private.closure_erasure_source_v5 c where singleton),'binding',private.closure_erasure_binding_v5(),'admittedAttempts',(select count(*) from public.notification_push_attempts where single_target_admission is not null),'ledgerRows',(select count(*) from supabase_migrations.schema_migrations)) result) q;if jsonb_array_length(observation->'problems')<>0 then raise exception 'promotion_postflight: %',observation->'problems' using errcode='55000';end if;end $promotion_postflight$;
notify pgrst,'reload schema';
commit;
